    LANGUAGE_WRAPPER = 'A biased random walk starts at 0 and at each step moves +1 with probability {p} and -1 with probability 1-{p}, where {p} is in (1/2,1). Fix positive integers {r} and {s}. For an integer n, let x(n) be the probability that the walk hits +{r} for the first time exactly at step n. Let y be the probability that the walk is at position +{s} after {m} steps. Determine all integers n in the inclusive interval [{n_min},{n_max}] such that x(n) > (1-{p}) y. If the parity condition for x(n) (i.e., n ≡ {r} mod 2 and n ≥ {r}) or for y (i.e., {m} ≡ {s} mod 2 and {m} ≥ {s}) is violated, define that probability to be 0. After solving, summarize your final answer using the format: ### The final answer is: [n1, n2, ..., nk]'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
def binom(n,k):
    if k<0 or k>n: return 0
    return math.comb(n,k)
for _ in range(200):
    p = round(rng.uniform(0.55, 0.85), 2)
    r = rng.randint(2, 6)
    s = rng.randint(2, 6)
    # choose m with same parity as s and reasonably sized
    base_lo = max(s, 6)
    base_hi = base_lo + 30
    m = rng.randrange(base_lo, base_hi)
    if (m - s) % 2 != 0:
        m += 1
        if m >= base_hi:
            m -= 2
    # compute y; ensure nontrivial magnitude
    a_m = (m + s) // 2
    b_m = (m - s) // 2
    y = binom(m, a_m) * (p ** a_m) * ((1 - p) ** b_m)
    if not (1e-6 <= y <= 0.3):
        continue
    # choose search interval for n
    n_min = rng.randint(max(r, 4), max(r, 4) + 5)
    width = rng.randint(10, 18)
    n_max = n_min + width
    # candidates must match parity with r and be >= r
    candidates = [n for n in range(n_min, n_max + 1) if n >= r and (n - r) % 2 == 0]
    if len(candidates) < 3:
        continue
    T = (1 - p) * y
    winners = []
    max_x = 0.0
    for n in candidates:
        a = (n + r) // 2
        b = (n - r) // 2
        x = (r / n) * binom(n, a) * (p ** a) * ((1 - p) ** b)
        if x > T:
            winners.append(n)
        if x > max_x:
            max_x = x
    if max_x < 1e-8:
        continue
    if 1 <= len(winners) <= len(candidates) - 1:
        return {'p': p, 'r': r, 's': s, 'm': m, 'n_min': n_min, 'n_max': n_max}
# Fallback deterministic assignment if random tries fail (rare)
